/**
 * n8n Code — entrada subfluxo TERMOS SOFIA v4
 */
const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

return [
  {
    json: {
      id_cliente: String(body.id_cliente || ''),
      conversation_id: String(body.conversation_id || ''),
      ixc_id_cliente: String(body.ixc_id_cliente || body.ixc_cliente_id || ''),
      id_contrato_ixc: String(body.id_contrato_ixc || body.id_contrato || ''),
      nome: String(body.nome || ''),
      telefone: String(body.telefone || ''),
    },
  },
];

const base64 = $json.audio_base64;

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(base64, 'base64'),
  $json.nome_arquivo || 'audio.ogg',
  $json.mime_type || 'application/ogg'
);

return [
  {
    json: $('Normalizar Sofia').first().json,
    binary: {
      audio_fidelidade: binaryData,
    },
  },
];

/**
 * n8n Code — escolhe o registro de termo/contrato (PDF), não RG/selfie.
 * Entrada: resposta de cliente_contrato_assinatura_termo
 */
const ctx = $('Normalizar Sofia').first().json;
const rows = Array.isArray($json.registros) ? $json.registros : [];

if (!rows.length) {
  throw new Error(
    `Nenhum registro em cliente_contrato_assinatura_termo para contrato ${ctx.id_contrato_ixc || '?'}`,
  );
}

const norm = (v) => String(v ?? '').toLowerCase();

const textoRegistro = (r) =>
  [
    r.tipo,
    r.tipo_documento,
    r.tipo_doc,
    r.descricao,
    r.nome,
    r.documento,
    r.modelo_termo,
    r.termo,
    r.obs,
    r.arquivo,
    r.extensao,
    r.mime_type,
  ]
    .map(norm)
    .join(' ');

const isIdentity = (r) =>
  /identidade|documento pessoal|\brg\b|\bcnh\b|selfie|rosto|facial|comprovante|foto/.test(
    textoRegistro(r),
  );

const isTermo = (r) =>
  /termo|fidelidade|contrato|ades[aã]o|assinatura digital/.test(textoRegistro(r)) &&
  !isIdentity(r);

const isPdf = (r) => {
  const t = textoRegistro(r);
  return t.includes('pdf') || t.includes('application/pdf');
};

const byIdAsc = (a, b) => Number(a.id || 0) - Number(b.id || 0);

let chosen =
  rows.find((r) => isTermo(r) && isPdf(r)) ||
  rows.find((r) => isTermo(r)) ||
  rows.find((r) => isPdf(r) && !isIdentity(r)) ||
  rows.filter((r) => !isIdentity(r)).sort(byIdAsc)[0] ||
  rows.slice().sort(byIdAsc)[0];

if (!chosen?.id) {
  throw new Error('Registro de termo sem id válido');
}

return [
  {
    json: {
      ...ctx,
      id_termo_ixc: String(chosen.id),
      termo_debug: {
        total: rows.length,
        escolhido_id: chosen.id,
        escolhido_tipo: chosen.tipo || chosen.tipo_documento || '',
        escolhido_nome: chosen.nome || chosen.descricao || '',
      },
    },
  },
];

/**
 * n8n Code — garante PDF antes de enviar ao Chatwoot
 * n8n 2.x: binary vem em $input.first().binary (não existe $binary global).
 */
const ctx =
  $('Selecionar termo PDF').first()?.json ||
  $('Normalizar Sofia').first()?.json ||
  {};

const item = $input.first();
const binary = item?.binary || {};
const bin = binary['attachments[]'] || binary.data;

if (!bin) {
  throw new Error('IXC não retornou arquivo do termo');
}

const mime = String(
  bin.mimeType || bin.mimetype || bin.fileType || '',
).toLowerCase();
const name = String(bin.fileName || bin.fileExtension || '').toLowerCase();

if (!mime.includes('pdf') && !name.endsWith('.pdf')) {
  throw new Error(
    `Arquivo errado (esperado PDF, veio ${mime || name || 'desconhecido'}). ` +
      `id_termo=${ctx.id_termo_ixc || '?'}`,
  );
}

return [
  {
    json: ctx,
    binary,
  },
];

/**
 * n8n Code — resposta TERMOS v4 para Eva/Sofia
 *
 * Fluxo linear: áudio → IXC termos → PDF Chatwoot.
 * Se o PDF foi (termoOk), o áudio já passou — mesmo que o HTTP do áudio
 * não traga id/message_type no JSON (comum em multipart no n8n 2.x).
 */
function chatwootOk(json) {
  if (!json || typeof json !== 'object') return false;
  if (json.error || json.errorMessage || json.errorDescription) return false;

  const status = Number(json.statusCode || json.status || 0);
  if (status >= 400) return false;
  if (status >= 200 && status < 300 && (json.id || json.content != null)) return true;

  const mt = json.message_type;
  if (mt === 'outgoing' || mt === 1 || mt === '1') return true;
  if (json.id) return true;
  if (json.content != null) return true;
  if (json.payload) return true;
  if (json.status === 'sent' || json.status === 'delivered') return true;

  const nested = json.message || json.data?.message || json.data;
  if (nested && typeof nested === 'object' && (nested.id || nested.content != null)) {
    return true;
  }

  return false;
}

function nodeOk(name) {
  try {
    const items = $(name).all();
    if (!items.length) return false;
    return items.some((item) => chatwootOk(item.json || {}));
  } catch {
    return false;
  }
}

function nodeExecutou(name) {
  try {
    return $(name).all().length > 0;
  } catch {
    return false;
  }
}

function audioProvavelmenteOk() {
  const candidatos = [
    'envia audio',
    'Envia audio',
    'envia_audio',
  ];
  for (const nome of candidatos) {
    if (nodeOk(nome)) return true;
  }
  for (const nome of candidatos) {
    if (nodeExecutou(nome)) return true;
  }
  // Fallback: qualquer nó cujo nome contenha "audio" e tenha rodado
  try {
    for (const nome of Object.keys($workflow?.nodes || {})) {
      if (!/audio/i.test(nome)) continue;
      if (nodeOk(nome) || nodeExecutou(nome)) return true;
    }
  } catch {
    /* n8n 2.x pode não expor $workflow */
  }
  return false;
}

let audioOk = audioProvavelmenteOk();
const termoOk = nodeOk('Envia_chatwoot') || nodeOk('Envia chatwoot');

// Neste workflow o PDF só existe se o ramo do áudio teve sucesso
if (!audioOk && termoOk) {
  audioOk = true;
}

const ok = audioOk && termoOk;

return [
  {
    json: {
      resultado: ok ? 'ok' : 'erro',
      audio_enviado: audioOk,
      termo_enviado: termoOk,
      motivo: ok
        ? 'Áudio e termo enviados no Chatwoot'
        : `Parcial: audio=${audioOk} termo=${termoOk}`,
      erro: !ok,
      transferir: !termoOk,
    },
  },
];
